export function main(a: Outer, b: Nullable | undefined) { return [a, b]; }
type Outer = Inner;
export type Inner = Date;
type Nullable = Date | null;

import type { Stamp } from "./types";
interface When extends Date {}
export function main(a: Date | string, b: When, c: Stamp, e, f: Array<Date>) { return [a, b, c, e, f]; }

type A = B;
type B = A;
export function main(d: A) { return d; }
